+package capture
+
+import (
+	"container/heap"
+	"context"
+	"sync"
+	"time"
+
+	"github.com/charmbracelet/log"
+)
+
+// maxReorderBytes bounds the packet data the reorder buffer holds. Past it, the oldest packets
+// are written early, which can put them out of order.
+const maxReorderBytes = 64 << 20
+
+// Reorder writes the packets of several capture sources in timestamp order.
+//
+// Each source (a node's capture stream, or a local interface socket) delivers its packets with
+// its own delay. The buffer holds every packet for `window` after it arrived and writes the held
+// packets in timestamp order, so a packet that was stamped earlier but delivered up to `window`
+// later still goes out first. A packet stamped before the last packet written arrived too late
+// to be ordered: it is written as it comes and counted, and the count goes to the debug log when
+// the capture ends.
+//
+// A source can place a hold at the earliest timestamp it may still write (Hold); packets stamped
+// after a hold wait for it to be released (Release). The c9s runtime holds while it switches
+// between chained capture segments.
+type Reorder struct {
+	write  func(id uint32, packet *Packet) error
+	onFail func()
+	window time.Duration
+	now    func() time.Time
+
+	mu     sync.Mutex
+	queue  reorderQueue
+	bytes  int
+	seq    uint64
+	holds  map[any]int64
+	err    error
+	wake   chan struct{}
+	stats  reorderStats
+	cursor int64 // timestamp of the latest packet written in order
+}
+
+type reorderStats struct {
+	late    int
+	maxLate time.Duration
+	forced  int
+}
+
+// reorderedPacket is a packet waiting in the buffer.
+type reorderedPacket struct {
+	id      uint32
+	packet  *Packet
+	arrived time.Time
+	seq     uint64
+}
+
+// reorderQueue is a min-heap by timestamp, then arrival.
+type reorderQueue []reorderedPacket
+
+func (q reorderQueue) Len() int { return len(q) }
+
+func (q reorderQueue) Less(i, j int) bool {
+	if q[i].packet.Timestamp != q[j].packet.Timestamp {
+		return q[i].packet.Timestamp < q[j].packet.Timestamp
+	}
+
+	return q[i].seq < q[j].seq
+}
+
+func (q reorderQueue) Swap(i, j int) { q[i], q[j] = q[j], q[i] }
+
+func (q *reorderQueue) Push(
+	x any,
+) {
+	*q = append(*q, x.(reorderedPacket))
+} //nolint:forcetypeassert // heap contract
+
+func (q *reorderQueue) Pop() any {
+	old := *q
+	item := old[len(old)-1]
+	*q = old[:len(old)-1]
+
+	return item
+}
+
+// NewReorder returns a buffer that writes through write; onFail is called once a write
+// failed. A window of zero or less writes every packet as it arrives.
+func NewReorder(
+	window time.Duration,
+	write func(id uint32, packet *Packet) error,
+	onFail func(),
+) *Reorder {
+	return &Reorder{
+		write: write, onFail: onFail, window: window, now: time.Now,
+		holds: map[any]int64{}, wake: make(chan struct{}, 1),
+	}
+}
+
+// push hands a packet to the buffer. It returns the error of a failed write.
+func (q *Reorder) Push(id uint32, packet *Packet) error {
+	q.mu.Lock()
+	defer q.mu.Unlock()
+
+	if q.err != nil {
+		return q.err
+	}
+	if q.window <= 0 {
+		return q.writeLocked(id, packet)
+	}
+	if q.cursor != 0 && packet.Timestamp < q.cursor {
+		q.stats.late++
+		q.stats.maxLate = max(q.stats.maxLate, time.Duration(q.cursor-packet.Timestamp))
+		if q.stats.late == 1 {
+			log.Debug("Capture packet arrived after the reorder window, writing it out of order",
+				"late_by", time.Duration(q.cursor-packet.Timestamp), "window", q.window)
+		}
+
+		return q.writeLocked(id, packet)
+	}
+
+	q.seq++
+	heap.Push(&q.queue, reorderedPacket{id: id, packet: packet, arrived: q.now(), seq: q.seq})
+	q.bytes += len(packet.Data)
+	for q.bytes > maxReorderBytes && q.queue.Len() > 0 {
+		q.stats.forced++
+		if err := q.popLocked(); err != nil {
+			return err
+		}
+	}
+
+	select {
+	case q.wake <- struct{}{}:
+	default:
+	}
+
+	return nil
+}
+
+// hold keeps packets stamped after timestamp in the buffer until release(key).
+func (q *Reorder) Hold(key any, timestamp int64) {
+	q.mu.Lock()
+	defer q.mu.Unlock()
+
+	q.holds[key] = timestamp
+}
+
+// release removes the hold of key.
+func (q *Reorder) Release(key any) {
+	q.mu.Lock()
+	_, held := q.holds[key]
+	delete(q.holds, key)
+	q.mu.Unlock()
+
+	if held {

metadata.preview:
+		select {
+		case q.wake <- struct{}{}:
+		default:
+		}
+	}
+}
+
+// run writes due packets until ctx ends.
+func (q *Reorder) Run(ctx context.Context) {
+	if q.window <= 0 {
+		return
+	}
+
+	timer := time.NewTimer(time.Hour)
+	defer timer.Stop()
+
+	for {
+		next := q.writeDue()
+		wait := time.Hour
+		if !next.IsZero() {

display.text:
+		select {
+		case q.wake <- struct{}{}:
+		default:
+		}
+	}
+}
+
+// run writes due packets until ctx ends.
+func (q *Reorder) Run(ctx context.Context) {
+	if q.window <= 0 {
+		return
+	}
+
+	timer := time.NewTimer(time.Hour)
+	defer timer.Stop()
+
+	for {
+		next := q.writeDue()
+		wait := time.Hour
+		if !next.IsZero() {
+			wait = max(next.Sub(q.now()), time.Millisecond)
+		}
+		resetTimer(timer, wait)
+
+		select {
+		case <-ctx.Done():
+			return
+		case <-q.wake:
+		case <-timer.C:
+		}
+	}
+}
+
+// writeDue writes the packets that waited for the window and are not behind a hold, in
+// timestamp order. It returns when the next packet is due, or zero when that depends on a new
+// packet or a released hold.
+func (q *Reorder) writeDue() time.Time {
+	q.mu.Lock()
+	defer q.mu.Unlock()
+
+	held, limit := false, int64(0)
+	for _, timestamp := range q.holds {
+		if !held || timestamp < limit {
+			held, limit = true, timestamp
+		}
+	}
+
+	now := q.now()
+	for q.queue.Len() > 0 && q.err == nil {
+		head := q.queue[0]
+		if held && head.packet.Timestamp > limit {
+			return time.Time{}
+		}
+		if due := head.arrived.Add(q.window); due.After(now) {
+			return due
+		}
+		if q.popLocked() != nil {
+			return time.Time{}
+		}
+	}
+
+	return time.Time{}
+}
+
+// flush writes every remaining packet in timestamp order and logs what could not be ordered.
+func (q *Reorder) Flush() {
+	q.mu.Lock()
+	defer q.mu.Unlock()
+
+	for q.queue.Len() > 0 && q.err == nil {
+		if q.popLocked() != nil {
+			break
+		}
+	}
+	q.queue, q.bytes = nil, 0
+
+	if q.stats.late > 0 || q.stats.forced > 0 {
+		log.Debug("Capture wrote packets out of timestamp order",
+			"late_packets", q.stats.late, "max_late_by", q.stats.maxLate,
+			"window", q.window, "buffer_overflow_packets", q.stats.forced)
+	}
+}
+
+func (q *Reorder) popLocked() error {
+	item := heap.Pop(&q.queue).(reorderedPacket) //nolint:forcetypeassert // heap contract
+	q.bytes -= len(item.packet.Data)
+	q.cursor = max(q.cursor, item.packet.Timestamp)
+
+	return q.writeLocked(item.id, item.packet)
+}
+
+func (q *Reorder) writeLocked(id uint32, packet *Packet) error {
+	if err := q.write(id, packet); err != nil {
+		if q.err == nil {
+			q.err = err
+			if q.onFail != nil {
+				q.onFail()
+			}
+		}
+
+		return err
+	}
+
+	return nil
+}
+
+func resetTimer(timer *time.Timer, d time.Duration) {
+	if !timer.Stop() {
+		select {
+		case <-timer.C:
+		default:
+		}
+	}
+	timer.Reset(d)
+}
diff --git a/capture/reorder_test.go b/capture/reorder_test.go
new file mode 100644
index 0000000..d281bed
--- /dev/null
+++ b/capture/reorder_test.go
@@ -0,0 +1,202 @@
+package capture
+
+import (
+	"context"
+	"errors"
+	"slices"
+	"sync"
+	"testing"
+	"time"
+)
+
+// reorderSink records what a reorder buffer writes.
+type reorderSink struct {
+	mu      sync.Mutex
+	written []int64
+	ids     []uint32
+	failAt  int
+}
+
+func (s *reorderSink) write(id uint32, packet *Packet) error {
+	s.mu.Lock()
+	defer s.mu.Unlock()
+	if s.failAt > 0 && len(s.written) == s.failAt {
+		return errors.New("write |1: broken pipe")
+	}
+	s.written = append(s.written, packet.Timestamp)
+	s.ids = append(s.ids, id)
+
+	return nil
+}
+
+func (s *reorderSink) timestamps() []int64 {
+	s.mu.Lock()
+	defer s.mu.Unlock()
+
+	return slices.Clone(s.written)
+}
+
+// interleavedStreams pushes two synthetic streams of ticks, interleaved in time: stream 0 is
+// delivered at once, stream 1 `delay` after its packets were stamped. Both stamp a packet every
+// 2 ms, offset by 1 ms.
+func interleavedStreams(t *testing.T, q *Reorder, ticks int, delay time.Duration) {
+	t.Helper()
+
+	start := time.Now()
+	type delivery struct {
+		at time.Time
+		id uint32
+		ts int64
+	}
+	var deliveries []delivery
+	for tick := range ticks {
+		stamp := start.Add(time.Duration(tick) * 2 * time.Millisecond)
+		deliveries = append(deliveries,
+			delivery{at: stamp, id: 0, ts: stamp.UnixNano()},
+			delivery{
+				at: stamp.Add(time.Millisecond + delay), id: 1,
+				ts: stamp.Add(time.Millisecond).UnixNano(),
+			})
+	}
+	slices.SortStableFunc(deliveries, func(a, b delivery) int { return a.at.Compare(b.at) })
+
+	for _, next := range deliveries {
+		time.Sleep(time.Until(next.at))
+		if err := q.Push(
+			next.id,
+			&Packet{InterfaceID: next.id, Timestamp: next.ts},
+		); err != nil {
+			t.Fatal(err)
+		}
+	}
+}
+
+func runReorder(q *Reorder) func() {
+	ctx, cancel := context.WithCancel(context.Background())
+	done := make(chan struct{})
+	go func() {
+		defer close(done)
+		q.Run(ctx)
+	}()
+
+	return func() {
+		cancel()
+		<-done
+		q.Flush()
+	}
+}
+
+func TestReorderOrdersStreamsWithinTheWindow(t *testing.T) {
+	t.Parallel()
+
+	sink := &reorderSink{}
+	q := NewReorder(100*time.Millisecond, sink.write, nil)
+	stop := runReorder(q)
+	interleavedStreams(t, q, 60, 40*time.Millisecond)
+
+	// packets go out while the capture runs, not only at the end
+	time.Sleep(150 * time.Millisecond)
+	if len(sink.timestamps()) == 0 {
+		t.Fatal("nothing written while the streams ran")
+	}
+	stop()
+
+	written := sink.timestamps()
+	if len(written) != 120 || !slices.IsSorted(written) {
+		t.Fatalf("written %d packets, sorted %v", len(written), slices.IsSorted(written))
+	}
+	if q.stats.late != 0 {
+		t.Fatalf("late packets = %d", q.stats.late)
+	}
+}
+
+func TestReorderWritesLatePacketsAsTheyCome(t *testing.T) {
+	t.Parallel()
+
+	sink := &reorderSink{}
+	q := NewReorder(20*time.Millisecond, sink.write, nil)
+	stop := runReorder(q)
+	// stream 1 arrives 80 ms after its stamps, far beyond the 20 ms window
+	interleavedStreams(t, q, 60, 80*time.Millisecond)
+	stop()
+
+	written := sink.timestamps()
+	if len(written) != 120 {
+		t.Fatalf("written %d packets, want all 120", len(written))
+	}
+	if q.stats.late == 0 || q.stats.maxLate < 40*time.Millisecond || slices.IsSorted(written) {
+		t.Fatalf("late = %d (max %s), sorted %v; want late packets written out of order",
+			q.stats.late, q.stats.maxLate, slices.IsSorted(written))
+	}
+}
+
+func TestReorderHoldsPacketsAfterAHold(t *testing.T) {
+	t.Parallel()
+
+	sink := &reorderSink{}
+	q := NewReorder(time.Millisecond, sink.write, nil)
+	stop := runReorder(q)
+	defer stop()
+
+	chain := &struct{ name string }{"chain"}
+	q.Hold(chain, 100)
+	for _, ts := range []int64{50, 150, 100, 200} {
+		if err := q.Push(0, &Packet{Timestamp: ts}); err != nil {
+			t.Fatal(err)
+		}
+	}
+	time.Sleep(30 * time.Millisecond)
+	if got := sink.timestamps(); !slices.Equal(got, []int64{50, 100}) {
+		t.Fatalf("written under the hold = %v, want [50 100]", got)
+	}
+
+	// the chain writes what it held back, then releases
+	if err := q.Push(1, &Packet{Timestamp: 120}); err != nil {
+		t.Fatal(err)
+	}
+	q.Release(chain)
+	time.Sleep(30 * time.Millisecond)
+	if got := sink.timestamps(); !slices.Equal(got, []int64{50, 100, 120, 150, 200}) {
+		t.Fatalf("written after the release = %v", got)
+	}
+}
+
+func TestReorderStopsAtTheFirstWriteError(t *testing.T) {
+	t.Parallel()
+
+	sink := &reorderSink{failAt: 2}
+	failed := 0
+	q := NewReorder(time.Millisecond, sink.write, func() { failed++ })
+	stop := runReorder(q)
+
+	var err error
+	for ts := int64(1); ts < 50 && err == nil; ts++ {
+		err = q.Push(0, &Packet{Timestamp: ts})
+		time.Sleep(2 * time.Millisecond)
+	}
+	stop()
+
+	if err == nil || failed != 1 || len(sink.timestamps()) != 2 {
+		t.Fatalf(
+			"push error = %v, onFail calls %d, written %d",
+			err,
+			failed,
+			len(sink.timestamps()),
+		)
+	}
+}
+
+func TestReorderWithoutWindowWritesThrough(t *testing.T) {
+	t.Parallel()
+
+	sink := &reorderSink{}
+	q := NewReorder(0, sink.write, nil)
+	for _, ts := range []int64{30, 10, 20} {
+		if err := q.Push(0, &Packet{Timestamp: ts}); err != nil {
+			t.Fatal(err)
+		}
+	}
+	if got := sink.timestamps(); !slices.Equal(got, []int64{30, 10, 20}) {
+		t.Fatalf("written = %v, want arrival order", got)
+	}
+}
diff --git a/cmd/capture.go b/cmd/capture.go
