display.text:
package capture

import (
	"container/heap"
	"context"
	"sync"
	"time"

	"github.com/charmbracelet/log"
)

// maxReorderBytes bounds the packet data the reorder buffer holds. Past it, the oldest packets
// are written early, which can put them out of order.
const maxReorderBytes = 64 << 20

// Reorder writes the packets of several capture sources in timestamp order.
//
// Each source (a node's capture stream, or a local interface socket) delivers its packets with
// its own delay. The buffer holds every packet for `window` after it arrived and writes the held
// packets in timestamp order, so a packet that was stamped earlier but delivered up to `window`
// later still goes out first. A packet stamped before the last packet written arrived too late
// to be ordered: it is written as it comes and counted, and the count goes to the debug log when
// the capture ends.
//
// A source can place a hold at the earliest timestamp it may still write (Hold); packets stamped
// after a hold wait for it to be released (Release). The c9s runtime holds while it switches
// between chained capture segments.
type Reorder struct {
	write  func(id uint32, packet *Packet) error
	onFail func()
	window time.Duration
	now    func() time.Time

	mu     sync.Mutex
	queue  reorderQueue
	bytes  int
	seq    uint64
	holds  map[any]int64
	err    error
	wake   chan struct{}
	stats  reorderStats
	cursor int64 // timestamp of the latest packet written in order
}

type reorderStats struct {
	late    int
	maxLate time.Duration
	forced  int
}

// reorderedPacket is a packet waiting in the buffer.
type reorderedPacket struct {
	id      uint32
	packet  *Packet
	arrived time.Time
	seq     uint64
}

// reorderQueue is a min-heap by timestamp, then arrival.
type reorderQueue []reorderedPacket

func (q reorderQueue) Len() int { return len(q) }

func (q reorderQueue) Less(i, j int) bool {
	if q[i].packet.Timestamp != q[j].packet.Timestamp {
		return q[i].packet.Timestamp < q[j].packet.Timestamp
	}

	return q[i].seq < q[j].seq
}

func (q reorderQueue) Swap(i, j int) { q[i], q[j] = q[j], q[i] }

func (q *reorderQueue) Push(
	x any,
) {
	*q = append(*q, x.(reorderedPacket))
} //nolint:forcetypeassert // heap contract

func (q *reorderQueue) Pop() any {
	old := *q
	item := old[len(old)-1]
	*q = old[:len(old)-1]

	return item
}

// NewReorder returns a buffer that writes through write; onFail is called once a write
// failed. A window of zero or less writes every packet as it arrives.
func NewReorder(
	window time.Duration,
	write func(id uint32, packet *Packet) error,
	onFail func(),
) *Reorder {
	return &Reorder{
		write: write, onFail: onFail, window: window, now: time.Now,
		holds: map[any]int64{}, wake: make(chan struct{}, 1),
	}
}

// push hands a packet to the buffer. It returns the error of a failed write.
func (q *Reorder) Push(id uint32, packet *Packet) error {
	q.mu.Lock()
	defer q.mu.Unlock()

	if q.err != nil {
		return q.err
	}
	if q.window <= 0 {
		return q.writeLocked(id, packet)
	}
	if q.cursor != 0 && packet.Timestamp < q.cursor {
		q.stats.late++
		q.stats.maxLate = max(q.stats.maxLate, time.Duration(q.cursor-packet.Timestamp))
		if q.stats.late == 1 {
			log.Debug("Capture packet arrived after the reorder window, writing it out of order",
				"late_by", time.Duration(q.cursor-packet.Timestamp), "window", q.window)
		}

		return q.writeLocked(id, packet)
	}

	q.seq++
	heap.Push(&q.queue, reorderedPacket{id: id, packet: packet, arrived: q.now(), seq: q.seq})
	q.bytes += len(packet.Data)
	for q.bytes > maxReorderBytes && q.queue.Len() > 0 {
		q.stats.forced++
		if err := q.popLocked(); err != nil {
			return err
		}
	}

	select {
	case q.wake <- struct{}{}:
	default:
	}

	return nil
}

// hold keeps packets stamped after timestamp in the buffer until release(key).
func (q *Reorder) Hold(key any, timestamp int64) {
	q.mu.Lock()
	defer q.mu.Unlock()

	q.holds[key] = timestamp
}

// release removes the hold of key.
func (q *Reorder) Release(key any) {
	q.mu.Lock()
	_, held := q.holds[key]
	delete(q.holds, key)
	q.mu.Unlock()

	if held {
		select {
		case q.wake <- struct{}{}:
		default:
		}
	}
}

// run writes due packets until ctx ends.
func (q *Reorder) Run(ctx context.Context) {
	if q.window <= 0 {
		return
	}

	timer := time.NewTimer(time.Hour)
	defer timer.Stop()

	for {
		next := q.writeDue()
		wait := time.Hour
		if !next.IsZero() {
			wait = max(next.Sub(q.now()), time.Millisecond)
		}
		resetTimer(timer, wait)

		select {
		case <-ctx.Done():
			return
		case <-q.wake:
		case <-timer.C:
		}
	}
}

// writeDue writes the packets that waited for the window and are not behind a hold, in
// timestamp order. It returns when the next packet is due, or zero when that depends on a new
// packet or a released hold.
func (q *Reorder) writeDue() time.Time {
	q.mu.Lock()
	defer q.mu.Unlock()

	held, limit := false, int64(0)
	for _, timestamp := range q.holds {
		if !held || timestamp < limit {
			held, limit = true, timestamp
		}
	}

	now := q.now()
	for q.queue.Len() > 0 && q.err == nil {
		head := q.queue[0]
		if held && head.packet.Timestamp > limit {
			return time.Time{}
		}
		if due := head.arrived.Add(q.window); due.After(now) {
			return due
		}
		if q.popLocked() != nil {
			return time.Time{}
		}
	}

	return time.Time{}
}

// flush writes every remaining packet in timestamp order and logs what could not be ordered.
func (q *Reorder) Flush() {
	q.mu.Lock()
	defer q.mu.Unlock()

	for q.queue.Len() > 0 && q.err == nil {
		if q.popLocked() != nil {
			break
		}
	}
	q.queue, q.bytes = nil, 0

	if q.stats.late > 0 || q.stats.forced > 0 {
		log.Debug("Capture wrote packets out of timestamp order",
			"late_packets", q.stats.late, "max_late_by", q.stats.maxLate,
			"window", q.window, "buffer_overflow_packets", q.stats.forced)
	}
}

func (q *Reorder) popLocked() error {
	item := heap.Pop(&q.queue).(reorderedPacket) //nolint:forcetypeassert // heap contract
	q.bytes -= len(item.packet.Data)
	q.cursor = max(q.cursor, item.packet.Timestamp)

	return q.writeLocked(item.id, item.packet)
}

func (q *Reorder) writeLocked(id uint32, packet *Packet) error {
	if err := q.write(id, packet); err != nil {
		if q.err == nil {
			q.err = err
			if q.onFail != nil {
				q.onFail()
			}
		}

		return err
	}

	return nil
}

func resetTimer(timer *time.Timer, d time.Duration) {
	if !timer.Stop() {
		select {
		case <-timer.C:
		default:
		}
	}
	timer.Reset(d)
}

package capture

import (
	"context"
	"fmt"
	"io"
	"strings"
	"sync/atomic"
	"time"

	"github.com/charmbracelet/log"
	clablabruntime "github.com/srl-labs/containerlab/labruntime"
)

// Snap length bounds of a capture.
const (
	// DefaultSnapLength is the snap length of a request without one.
	DefaultSnapLength = 256 << 10
	MinSnapLength     = 64
	MaxSnapLength     = 1 << 20
)

// ValidateRequest checks the bounds of a capture request and fills the default snap length.
func ValidateRequest(req *clablabruntime.CaptureRequest) error {
	if req.Name == "" {
		return fmt.Errorf("topology name is required")
	}
	if len(req.Targets) == 0 {
		return fmt.Errorf("at least one capture target (node and interface) is required")
	}
	for _, target := range req.Targets {
		if target.Node == "" || target.Interface == "" {
			return fmt.Errorf("capture target %+v needs a node and an interface", target)
		}
	}
	if req.Duration < 0 {
		return fmt.Errorf("capture duration must not be negative")
	}
	if req.PacketLimit < 0 {
		return fmt.Errorf("capture packet limit must not be negative")
	}
	if req.SnapLength == 0 {
		req.SnapLength = DefaultSnapLength
	}
	if req.SnapLength < MinSnapLength || req.SnapLength > MaxSnapLength {
		return fmt.Errorf("capture snap length %d is outside %d to %d bytes", req.SnapLength,
			MinSnapLength, MaxSnapLength)
	}

	return nil
}

// FindInterface matches a requested interface by its name, then by its alias.
func FindInterface(
	entries []clablabruntime.CaptureInterface,
	name string,
) (clablabruntime.CaptureInterface, bool) {
	for _, entry := range entries {
		if entry.Interface == name {
			return entry, true
		}
	}
	for _, entry := range entries {
		if entry.Alias != "" && entry.Alias == name {
			return entry, true
		}
	}

	return clablabruntime.CaptureInterface{}, false
}

// DescribeInterfaces lists interfaces for an error message: name (alias), ...
func DescribeInterfaces(entries []clablabruntime.CaptureInterface) string {
	if len(entries) == 0 {
		return "none"
	}

	names := make([]string, 0, len(entries))
	for _, entry := range entries {
		name := entry.Interface
		if entry.Alias != "" {
			name += " (" + entry.Alias + ")"
		}
		names = append(names, name)
	}

	return strings.Join(names, ", ")
}

// ReportGap hands a gap to onGap, or logs it as a warning when onGap is nil.
func ReportGap(onGap func(clablabruntime.CaptureGap), gap clablabruntime.CaptureGap) {
	if onGap != nil {
		onGap(gap)
		return
	}

	to := "unknown"
	if !gap.To.IsZero() {
		to = gap.To.Format(time.RFC3339Nano)
	}
	log.Warn("Capture has a gap", "node", gap.Node, "interfaces", strings.Join(gap.Interfaces, ","),
		"from", gap.From.Format(time.RFC3339Nano), "to", to, "reason", gap.Reason)
}

// Output is the merged pcapng stream of one capture: the section header with one interface per
// capture target, then the packets of every target in timestamp order (through a Reorder), up
// to an optional packet limit.
type Output struct {
	writer  *Writer
	reorder *Reorder
	limit   int64
	written atomic.Int64
	stop    func()

	cancelRun context.CancelFunc
	runDone   chan struct{}
}

// NewOutput writes the section header and one Interface Description Block per name to w, then
// starts the reorder buffer with the given window (zero or less writes packets as they come).
// stop is called once the packet limit is reached or a write failed. Close must be called.
func NewOutput(
	w io.Writer,
	names []string,
	snapLength, packetLimit int,
	window time.Duration,
	stop func(),
) (*Output, error) {
	writer := NewWriter(w)
	if err := writer.WriteHeader(
		names,
		uint32(snapLength),
	); err != nil { //nolint:gosec // validated
		return nil, err
	}

	out := &Output{
		writer:  writer,
		reorder: NewReorder(window, writer.WritePacket, stop),
		limit:   int64(packetLimit),
		stop:    stop,
		runDone: make(chan struct{}),
	}

	var runCtx context.Context
	runCtx, out.cancelRun = context.WithCancel(context.Background())
	go func() {
		defer close(out.runDone)
		out.reorder.Run(runCtx)
	}()

	return out, nil
}

// Emit hands a packet of the interface with the given index to the stream. It reports false
// once the packet limit is reached and the capture stops, and returns the error of a failed
// write.
func (o *Output) Emit(id uint32, packet *Packet) (bool, error) {
	if o.limit > 0 {
		count := o.written.Add(1)
		if count > o.limit {
			o.stop()
			return false, nil
		}
		if err := o.reorder.Push(id, packet); err != nil {
			return false, err
		}
		if count == o.limit {
			o.stop()
			return false, nil
		}

		return true, nil
	}

	o.written.Add(1)

	return true, o.reorder.Push(id, packet)
}

// Written returns the number of packets handed to the stream so far.
func (o *Output) Written() int64 {
	return o.written.Load()
}

// Hold keeps packets stamped after timestamp back until Release(key).
func (o *Output) Hold(key any, timestamp int64) {
	o.reorder.Hold(key, timestamp)
}

// Release removes the hold of key.
func (o *Output) Release(key any) {
	o.reorder.Release(key)
}

// Close writes the packets still held back and returns the first write error.
func (o *Output) Close() error {
	o.cancelRun()
	<-o.runDone
	o.reorder.Flush()

	return o.writer.Err()
}

